#include <cstdint>

uint32_t mul16(uint16_t a, uint16_t b) { return static_cast<uint32_t>(a) * b; }

uint64_t mul32x32(uint32_t a, uint32_t b) {
    uint16_t al = static_cast<uint16_t>(a), ah = static_cast<uint16_t>(a >> 16);
    uint16_t bl = static_cast<uint16_t>(b), bh = static_cast<uint16_t>(b >> 16);
    uint64_t ll = mul16(al, bl);
    uint64_t lh = mul16(al, bh);
    uint64_t hl = mul16(ah, bl);
    uint64_t hh = mul16(ah, bh);
    // lh + hl can exceed 32 bits, so add them in 64-bit before shifting.
    return (hh << 32) + ((lh + hl) << 16) + ll;
}

