#include <cstdint>

// Each step shortens every run of 1s by one bit; the number of steps
// until x becomes 0 is the length of the longest run.
int longestOnes(uint32_t x) {
    int k = 0;
    while (x) {
        x &= x << 1;
        ++k;
    }
    return k;
}
